Running command: cat > /workspace/repro6.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sdb.h"

int main(void) {
    Sdb *a, *b, *c;

    a = sdb_new0(); /* parent */
    b = sdb_new0(); /* child */
    c = sdb_new0(); /* grandchild */

    printf("Initial: a=%d b=%d c=%d\n", a->refs, b->refs, c->refs);

    /* b has two namespaces pointing to c */
    sdb_ns_set(b, "x", c);
    printf("After b->x: c=%d\n", c->refs);
    sdb_ns_set(b, "y", c);
    printf("After b->y: c=%d\n", c->refs);

    /* a has one namespace pointing to b */
    sdb_ns_set(a, "n", b);
    printf("After a->n: b=%d\n", b->refs);

    printf("Calling sdb_free(a)...\n");
    fflush(stdout);

    sdb_free(a);

    printf("Done\n");
    return 0;
}
EOF
cd /workspace && gcc -fsanitize=address -g -I /workspace/repo-vul/src-vul/radare2/shlr/sdb/src -o repro6 repro6.c /workspace/repo-vul/src-vul/radare2/shlr/sdb/src/libsdb.a -lpthread -ldl -lm 2>&1 && ./repro6; echo "Exit: $?"

